+fn create(world: &World, h: &mut History, op: PlasmaOp) {
+    let cmd = CreateOperation::new(world, "Plasma1", TORCH, SrcRef::Entity("plate".into()), OpParams::PlasmaProfile(op));
+    h.execute(world, cmd.expect("the operation is taken"));
